# 3 "../../mlp.cpp" 2





typedef enum {
    FSM_LOAD_INPUT = 0,
    FSM_LAYER1,
    FSM_LAYER2,
    FSM_LAYER3,
    FSM_WRITE_OUTPUT,
    FSM_DONE
} fsm_state_t;






inline data_t rescale_and_relu(acc_t acc) {
_ssdm_InlineSelf(0, "");
 acc_t rounded = (acc + (1 << (14 - 1))) >> 14;
    if (rounded <= 0) {
        return 0;
    } else if (rounded > 32767) {
        return 32767;
    } else {
        return (data_t)rounded;
    }
}

inline data_t rescale_linear(acc_t acc) {
_ssdm_InlineSelf(0, "");
 acc_t rounded = (acc + (1 << (14 - 1))) >> 14;
    if (rounded > 32767) {
        return 32767;
    } else if (rounded < -32768) {
        return -32768;
    } else {
        return (data_t)rounded;
    }
}






inline acc_t simd_mac16(const data_t act_slice[16], const weight_t w_slice[16]) {_ssdm_SpecArrayDimSize(act_slice, 16);_ssdm_SpecArrayDimSize(w_slice, 16);
_ssdm_InlineSelf(0, "");
 acc_t prod[16];
_ssdm_SpecArrayPartition( prod, 1, "COMPLETE", 0, "");


 SIMD_MUL: for (int k = 0; k < 16; ++k) {
_ssdm_Unroll(0,0,0, "");
 prod[k] = (acc_t)act_slice[k] * (acc_t)w_slice[k];
    }


    acc_t stage1[8];
_ssdm_SpecArrayPartition( stage1, 1, "COMPLETE", 0, "");
 TREE_L1: for (int k = 0; k < 8; ++k) {
_ssdm_Unroll(0,0,0, "");
 stage1[k] = prod[2*k] + prod[2*k + 1];
    }

    acc_t stage2[4];
_ssdm_SpecArrayPartition( stage2, 1, "COMPLETE", 0, "");
 TREE_L2: for (int k = 0; k < 4; ++k) {
_ssdm_Unroll(0,0,0, "");
 stage2[k] = stage1[2*k] + stage1[2*k + 1];
    }

    acc_t stage3[2];
_ssdm_SpecArrayPartition( stage3, 1, "COMPLETE", 0, "");
 stage3[0] = stage2[0] + stage2[1];
    stage3[1] = stage2[2] + stage2[3];

    return stage3[0] + stage3[1];
}




void mlp_accel(
    const data_t in_vec[784],
    data_t out_vec[10]
) {_ssdm_SpecArrayDimSize(in_vec, 784);_ssdm_SpecArrayDimSize(out_vec, 10);



_ssdm_op_SpecInterface(0, "s_axilite", 0, 0, "", 0, 0, "CTRL_BUS", "", "", 0, 0, 0, 0, "", "");
_ssdm_op_SpecInterface(in_vec, "s_axilite", 0, 0, "", 0, 0, "CTRL_BUS", "", "", 0, 0, 0, 0, "", "");
_ssdm_op_SpecInterface(out_vec, "s_axilite", 0, 0, "", 0, 0, "CTRL_BUS", "", "", 0, 0, 0, 0, "", "");





 data_t input_buf[(784 / 16)][16];
_ssdm_SpecArrayPartition( input_buf, 2, "COMPLETE", 0, "");



 data_t ping_buf[(128 / 16)][16];
_ssdm_SpecArrayPartition( ping_buf, 2, "COMPLETE", 0, "");


 data_t pong_buf[(64 / 16)][16];
_ssdm_SpecArrayPartition( pong_buf, 2, "COMPLETE", 0, "");


 data_t out_buf[10];
_ssdm_SpecArrayPartition( out_buf, 1, "COMPLETE", 0, "");





_ssdm_SpecArrayPartition( &weights_l1, 3, "COMPLETE", 0, "");
_ssdm_SpecArrayPartition( &weights_l2, 3, "COMPLETE", 0, "");
_ssdm_SpecArrayPartition( &weights_l3, 3, "COMPLETE", 0, "");




 fsm_state_t state = FSM_LOAD_INPUT;
    bool execution_active = true;

    EXEC_FSM: while (execution_active) {
_ssdm_op_SpecPipeline(0, 0, 0, 1, "");
 switch (state) {
            case FSM_LOAD_INPUT: {

                LOAD_LOOP_B: for (int b = 0; b < (784 / 16); ++b) {
_ssdm_op_SpecPipeline(1, 1, 1, 0, "");
 for (int k = 0; k < 16; ++k) {
_ssdm_Unroll(0,0,0, "");
 input_buf[b][k] = in_vec[b * 16 + k];
                    }
                }
                state = FSM_LAYER1;
                break;
            }

            case FSM_LAYER1: {


                L1_NEURONS: for (int n = 0; n < 128; ++n) {
                    acc_t acc = 0;
                    L1_BLOCKS_LOOP: for (int b = 0; b < (784 / 16); ++b) {
_ssdm_op_SpecPipeline(1, 1, 1, 0, "");
 data_t act_chunk[16];
                        weight_t w_chunk[16];
_ssdm_SpecArrayPartition( act_chunk, 1, "COMPLETE", 0, "");
_ssdm_SpecArrayPartition( w_chunk, 1, "COMPLETE", 0, "");

 FETCH_L1: for (int k = 0; k < 16; ++k) {
_ssdm_Unroll(0,0,0, "");
 act_chunk[k] = input_buf[b][k];
                            w_chunk[k] = weights_l1[n][b][k];
                        }
                        acc += simd_mac16(act_chunk, w_chunk);
                    }
                    ping_buf[n / 16][n % 16] = rescale_and_relu(acc);
                }
                state = FSM_LAYER2;
                break;
            }

            case FSM_LAYER2: {


                L2_NEURONS: for (int n = 0; n < 64; ++n) {
                    acc_t acc = 0;
                    L2_BLOCKS_LOOP: for (int b = 0; b < (128 / 16); ++b) {
_ssdm_op_SpecPipeline(1, 1, 1, 0, "");
 data_t act_chunk[16];
                        weight_t w_chunk[16];
_ssdm_SpecArrayPartition( act_chunk, 1, "COMPLETE", 0, "");
_ssdm_SpecArrayPartition( w_chunk, 1, "COMPLETE", 0, "");

 FETCH_L2: for (int k = 0; k < 16; ++k) {
_ssdm_Unroll(0,0,0, "");
 act_chunk[k] = ping_buf[b][k];
                            w_chunk[k] = weights_l2[n][b][k];
                        }
                        acc += simd_mac16(act_chunk, w_chunk);
                    }
                    pong_buf[n / 16][n % 16] = rescale_and_relu(acc);
                }
                state = FSM_LAYER3;
                break;
            }

            case FSM_LAYER3: {


                L3_NEURONS: for (int n = 0; n < 10; ++n) {
                    acc_t acc = 0;
                    L3_BLOCKS_LOOP: for (int b = 0; b < (64 / 16); ++b) {
_ssdm_op_SpecPipeline(1, 1, 1, 0, "");
 data_t act_chunk[16];
                        weight_t w_chunk[16];
_ssdm_SpecArrayPartition( act_chunk, 1, "COMPLETE", 0, "");
_ssdm_SpecArrayPartition( w_chunk, 1, "COMPLETE", 0, "");

 FETCH_L3: for (int k = 0; k < 16; ++k) {
_ssdm_Unroll(0,0,0, "");
 act_chunk[k] = pong_buf[b][k];
                            w_chunk[k] = weights_l3[n][b][k];
                        }
                        acc += simd_mac16(act_chunk, w_chunk);
                    }

                    out_buf[n] = rescale_linear(acc);
                }
                state = FSM_WRITE_OUTPUT;
                break;
            }

            case FSM_WRITE_OUTPUT: {

                WRITE_LOOP: for (int i = 0; i < 10; ++i) {
_ssdm_op_SpecPipeline(1, 1, 1, 0, "");
 out_vec[i] = out_buf[i];
                }
                state = FSM_DONE;
                break;
            }

            case FSM_DONE: {
                execution_active = false;
                break;
            }
        }
    }
}
